export const ICONS={auto:'Otomatik',walk:'Yürüyüş',fitness:'Spor',work:'İş',study:'Öğrenme',health:'Sağlık',food:'Yemek',social:'Buluşma',rest:'Dinlenme',home:'Ev',faith:'İbadet',call:'Arama',shopping:'Alışveriş',idea:'Fikir',calendar:'Takvim'};
const rules=[['walk',/yuruy|yuru|kosu|kosmak/],['fitness',/spor|fitness|antren|antreman|pilates|yoga|egzersiz/],['study',/ders|sinav|ingilizce|kitap|okuma|ogren|odev|tez|calisma plani/],['health',/doktor|hastane|ilac|disci|tahlil|saglik/],['food',/yemek|kahvalti|ogle yemegi|aksam yemegi|kahve/],['shopping',/alisveris|market|siparis/],['call',/ara(mak|ma)?\b|telefon|gorusme/],['work',/vardiya|depo|toplanti|mesai|is plani/],['rest',/uyku|dinlen|mola/],['faith',/namaz|ibadet|dua|cuma/],['social',/bulus|arkadas|aile|ziyaret/],['home',/temizlik|ev |camasir|bulasik/],['idea',/fikir|not al|merak/]];
export function inferIcon(title=''){const text=String(title).toLocaleLowerCase('tr').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i');return rules.find(([,pattern])=>pattern.test(text))?.[0]||'calendar';}
export function iconName(item={}){return item.icon&&item.icon!=='auto'&&Object.hasOwn(paths,item.icon)?item.icon:inferIcon(item.title);}
export function planIcon(item={},small=false){const name=iconName(item);return `<span class="plan-icon ${name}${small?' small':''}" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round">${paths[name]}</svg></span>`;}
export function iconEmoji(item={}){return {walk:'🚶',fitness:'🏋️',work:'💼',study:'📚',health:'🩺',food:'🍽️',social:'👥',rest:'🌙',home:'🏠',faith:'🕌',call:'📞',shopping:'🛒',idea:'💡',calendar:'📅'}[iconName(item)];}
